import { path } from '@servicenow/sdk-build-core'
import * as fs from 'fs'
import { createTestContext } from './test-utils'

describe('Mixed Pills Datapill Transformation Test Suite (XML -> Fluent)', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    test('Should transform XML with mixed UUID and semantic pills to Fluent wfa.dataPill() calls', async () => {
        // Read the XML file from the test directory
        const xmlPath = path.resolve(__dirname, 'mixed-pills/semantic_uuid_pills_issue.xml')
        const xmlContent = fs.readFileSync(xmlPath, 'utf-8')

        const project = ctx.createProject({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_snc_sample_flow', scopeId: 'df166f9b961b411a84664d0b9eedd8b6' },
        })

        // Transform XML -> Fluent
        const result = await project.transform({ path: 'semantic_uuid_pills_issue.xml', content: xmlContent })

        // Get the generated Fluent file
        const fluentFile = result.changedFiles.find((f) => f.getPath().includes('.now.ts'))
        expect(fluentFile).toBeDefined()

        if (!fluentFile) {
            throw new Error('No Fluent file generated')
        }

        const sourceCode = fluentFile.getContent()

        // Test Case 1: Verify wfa.dataPill() calls are present
        expect(sourceCode).toContain('wfa.dataPill(')

        // Test Case 2: Verify semantic pills are transformed correctly
        // Should have trigger references like _params.trigger.table_name
        expect(sourceCode).toContain('_params.trigger')

        // Test Case 3: Verify flow variable references
        // Should have flow variable references like _params.flowVariables
        expect(sourceCode).toContain('_params.flowVariables')

        // Test Case 4: Verify forEach logic is present (if forEach is in XML)
        if (sourceCode.includes('wfa.flowLogic.forEach')) {
            // ForEach should reference item_N parameter (where N is a number)
            expect(sourceCode).toMatch(/item_\d+/)
        }

        // Test Case 5: Verify multiple pills can coexist in template strings
        // Count the number of wfa.dataPill calls - should have multiple
        const dataPillMatches = sourceCode.match(/wfa\.dataPill\(/g)
        expect(dataPillMatches).not.toBeNull()
        if (dataPillMatches) {
            expect(dataPillMatches.length).toBeGreaterThan(1)
        }

        // Test Case 6: Verify template expressions with multiple pills
        // Look for template strings with multiple ${...} expressions
        const templateWithMultiplePills = /\$\{[^}]+\}[^`]*\$\{[^}]+\}/
        const hasMultiplePillsInTemplate = templateWithMultiplePills.test(sourceCode)
        if (hasMultiplePillsInTemplate) {
            // If we found template strings with multiple pills, verify they're properly formatted
            expect(sourceCode).toMatch(/wfa\.dataPill\([^)]+\)/)
        }
    })

    test('Should preserve forEach item references with UUID pills', async () => {
        const xmlPath = path.resolve(__dirname, 'mixed-pills/semantic_uuid_pills_issue.xml')
        const xmlContent = fs.readFileSync(xmlPath, 'utf-8')

        const project = ctx.createProject({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_snc_sample_flow', scopeId: 'df166f9b961b411a84664d0b9eedd8b6' },
        })

        const result = await project.transform({ path: 'semantic_uuid_pills_issue.xml', content: xmlContent })
        const fluentFile = result.changedFiles.find((f) => f.getPath().includes('.now.ts'))

        if (!fluentFile) {
            throw new Error('No Fluent file generated')
        }

        const sourceCode = fluentFile.getContent()

        // If forEach is present with UUID-based pills
        if (sourceCode.includes('wfa.flowLogic.forEach')) {
            // The forEach UUID should reference item_0.field_name (without redundant 'item.' prefix)
            // Look for patterns like: wfa.dataPill(item_0.field_name, ...)
            const forEachPillPattern = /wfa\.dataPill\(item_\d+\.\w+/
            expect(sourceCode).toMatch(forEachPillPattern)

            // Should NOT have redundant item.item.field_name patterns
            expect(sourceCode).not.toContain('item_0.item.item')
            expect(sourceCode).not.toMatch(/item_\d+\.item\.item/)
        }
    })

    test('Should handle action status pills mixed with semantic pills', async () => {
        const xmlPath = path.resolve(__dirname, 'mixed-pills/semantic_uuid_pills_issue.xml')
        const xmlContent = fs.readFileSync(xmlPath, 'utf-8')

        const project = ctx.createProject({
            packageJson: { name: 'test', version: '1.0.0' },
            config: { scope: 'x_snc_sample_flow', scopeId: 'df166f9b961b411a84664d0b9eedd8b6' },
        })

        const result = await project.transform({ path: 'semantic_uuid_pills_issue.xml', content: xmlContent })
        const fluentFile = result.changedFiles.find((f) => f.getPath().includes('.now.ts'))

        if (!fluentFile) {
            throw new Error('No Fluent file generated')
        }

        const sourceCode = fluentFile.getContent()

        // Look for action status references (UUID-based pills)
        // Pattern: actionInstance_N.__action_status__.code
        const actionStatusPattern = /actionInstance_\d+\.__action_status__/
        const hasMixedPills = actionStatusPattern.test(sourceCode) && sourceCode.includes('_params.trigger')

        if (hasMixedPills) {
            // Verify both types of pills are properly wrapped with wfa.dataPill
            expect(sourceCode).toMatch(/wfa\.dataPill\(actionInstance_\d+\.__action_status__/)
            expect(sourceCode).toMatch(/wfa\.dataPill\(_params\.trigger/)
        }
    })
})
